class Solution {
    public boolean containsDuplicate(int[] nums) {
        Set<Integer> seen = new HashSet<>(); // history of every value scanned so far
        for (int value : nums) {
            // add() fails exactly when value was already seen
            if (!seen.add(value)) return true;
        }
        return false;
    }
}

