class Solution {
    public boolean isAnagram(String s, String t) {
        // different lengths can never be anagrams
        if (s.length() != t.length()) return false;
        int[] count = new int[26]; // net count per letter across both strings
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++; // credit letters from s
            count[t.charAt(i) - 'a']--; // debit letters from t
        }
        for (int value : count) {
            // a nonzero count means the letters didn't cancel out
            if (value != 0) return false;
        }
        return true;
    }
}

