class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int value : nums) frequency.merge(value, 1, Integer::sum);

        // Bucket index = frequency, since frequency can never exceed nums.length.
        List<Integer>[] buckets = new List[nums.length + 1];
        for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
            int f = entry.getValue();
            if (buckets[f] == null) buckets[f] = new ArrayList<>();
            buckets[f].add(entry.getKey());
        }

        int[] answer = new int[k];
        int index = 0;
        // walk buckets high to low
        for (int f = buckets.length - 1; f >= 1 && index < k; f--) {
            if (buckets[f] == null) continue;
            for (int value : buckets[f]) {
                answer[index++] = value;
                if (index == k) break;
            }
        }
        return answer;
    }
}

