class Codec {
    public String encode(List<String> strs) {
        StringBuilder out = new StringBuilder();
        // length-prefix each string
        for (String s : strs) out.append(s.length()).append('#').append(s);
        return out.toString();
    }

    public List<String> decode(String encoded) {
        List<String> result = new ArrayList<>();
        int i = 0;
        while (i < encoded.length()) {
            int separator = i;
            // find the length prefix's end
            while (encoded.charAt(separator) != '#') separator++;
            int length = Integer.parseInt(encoded.substring(i, separator));
            int start = separator + 1;
            // read exactly `length` characters
            result.add(encoded.substring(start, start + length));
            i = start + length;
        }
        return result;
    }
}

