class Solution {
    public int characterReplacement(String s, int k) {
        int[] count = new int[26];
        // maxCount = historical maximum frequency; it may be stale after shrinking
        int left = 0, maxCount = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            maxCount = Math.max(maxCount, ++count[s.charAt(right) - 'A']);
            // The historical bound limits growth; a stale value cannot create a longer optimum
            while (right - left + 1 - maxCount > k) {
                count[s.charAt(left++) - 'A']--;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

minimum-window-substring.code:
class Solution {
    public String minWindow(String s, String t) {
        if (t.isEmpty() || s.length() < t.length()) return "";
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);

        Map<Character, Integer> window = new HashMap<>();
        // distinct characters fully satisfied so far
        int formed = 0, required = need.size();
        int left = 0, bestStart = 0, bestLength = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            int count = window.merge(c, 1, Integer::sum);
            if (need.containsKey(c) && count == need.get(c)) formed++;

            while (formed == required) { // window is valid, try to shrink it
                int length = right - left + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = left;
                }
                char removed = s.charAt(left++);
                int before = window.get(removed);
                if (need.containsKey(removed) && before == need.get(removed)) formed--;
                window.put(removed, before - 1);
            }
        }
        return bestLength == Integer.MAX_VALUE
            ? "" : s.substring(bestStart, bestStart + bestLength);
    }
}

