public class Solution {
    public boolean hasCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;      // moves one node per step
            fast = fast.next.next; // moves two nodes per step
            if (slow == fast) return true; // they can only meet if a cycle exists
        }
        return false;
    }
