class Solution {
    public ListNode mergeKLists(ListNode[] lists) {
        PriorityQueue<ListNode> heap =
            // orders by node value
            new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));
        for (ListNode node : lists) {
            if (node != null) heap.offer(node); // seed with each list's head
        }
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (!heap.isEmpty()) {
            ListNode node = heap.poll(); // smallest current head across all lists
            tail.next = node;
            tail = node;
            if (node.next != null) heap.offer(node.next); // replace it with its successor
        }
        return dummy.next;
    }
}

