class Solution {
    public boolean isSubtree(TreeNode root, TreeNode subRoot) {
        if (subRoot == null) return true;
        if (root == null) return false;
        return same(root, subRoot)              // try matching right here...
            || isSubtree(root.left, subRoot)     // ...or search the left subtree...
            || isSubtree(root.right, subRoot);   // ...or search the right subtree
    }

    private boolean same(TreeNode a, TreeNode b) { // exact structural + value match
        if (a == null || b == null) return a == b;
        return a.val == b.val && same(a.left, b.left) && same(a.right, b.right);
    }
}

