class Solution {
    public List<List<Integer>> levelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) return result;
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int size = queue.size(); // snapshot: exactly the nodes at the current depth
            List<Integer> level = new ArrayList<>(size);
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                level.add(node.val);
                // queued for the next depth
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            result.add(level);
        }
        return result;
    }
}

validate-binary-search-tree.code:
class Solution {
    public boolean isValidBST(TreeNode root) {
        // long avoids INT_MIN/MAX edge overflow
        return valid(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean valid(TreeNode node, long lower, long upper) {
        if (node == null) return true;
        // violates an ancestor's bound
        if (node.val <= lower || node.val >= upper) return false;
        // left subtree must stay below node.val
        return valid(node.left, lower, node.val)
            // right subtree must stay above node.val
            && valid(node.right, node.val, upper);
    }
}

