class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;
        while (true) {
            while (current != null) { // push the whole left spine
                stack.push(current);
                current = current.left;
            }
            current = stack.pop(); // next node in sorted (inorder) order
            if (--k == 0) return current.val;
            current = current.right;
        }
    }
}

construct-binary-tree-from-preorder-and-.code:
class Solution {
    private int preorderIndex;
    // value -> its position in inorder, for O(1) split lookup
    private Map<Integer, Integer> inorderIndex;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        preorderIndex = 0;
        inorderIndex = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) inorderIndex.put(inorder[i], i);
        return build(preorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int left, int right) {
        if (left > right) return null;
        // next unused preorder value is always the current root
        int value = preorder[preorderIndex++];
        TreeNode root = new TreeNode(value);
        // everything left of split is the left subtree, etc.
        int split = inorderIndex.get(value);
        root.left = build(preorder, left, split - 1);
        root.right = build(preorder, split + 1, right);
        return root;
    }
}

binary-tree-maximum-path-sum.code:
class Solution {
    private int best;

    public int maxPathSum(TreeNode root) {
        best = Integer.MIN_VALUE;
        gain(root);
        return best;
    }

    // best downward path starting at node, contributed to parent
    private int gain(TreeNode node) {
        if (node == null) return 0;
        int left = Math.max(0, gain(node.left));   // ignore a negative contribution
        int right = Math.max(0, gain(node.right));
        // path bending through both children, checked here only
        best = Math.max(best, node.val + left + right);
        // but only one branch can be handed up to the parent
        return node.val + Math.max(left, right);
    }
}

serialize-and-deserialize-binary-tree.code:
public class Codec {
    public String serialize(TreeNode root) {
        StringBuilder out = new StringBuilder();
        encode(root, out);
        return out.toString();
    }

    private void encode(TreeNode node, StringBuilder out) {
        if (node == null) {
            // explicit marker so decode knows exactly where branches end
            out.append("#,");
            return;
        }
        out.append(node.val).append(',');
        encode(node.left, out);  // preorder: root, then left, then right
        encode(node.right, out);
    }

    public TreeNode deserialize(String data) {
        String[] tokens = data.split(",");
        int[] index = {0}; // mutable cursor shared across recursive calls
        return decode(tokens, index);
    }

    private TreeNode decode(String[] tokens, int[] index) {
        String token = tokens[index[0]++];
        if (token.equals("#")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(token));
        node.left = decode(tokens, index);  // same preorder used during encoding
        node.right = decode(tokens, index);
        return node;
    }
}

find-median-from-data-stream.code:
class MedianFinder {
    // max-heap: top is the largest of the small half
    private final PriorityQueue<Integer> lower =
        new PriorityQueue<>(Comparator.reverseOrder());
    // min-heap: smallest of the large half
    private final PriorityQueue<Integer> upper = new PriorityQueue<>();

    public void addNum(int num) {
        lower.offer(num);
        // always route through lower first to keep values correctly split
        upper.offer(lower.poll());
        // rebalance if upper grew too big
        if (upper.size() > lower.size()) lower.offer(upper.poll());
    }

    public double findMedian() {
        // odd total: lower holds the extra value
        if (lower.size() > upper.size()) return lower.peek();
        // even total: average both middle values
        return ((long) lower.peek() + upper.peek()) / 2.0;
    }
}

combination-sum.code:
class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates); // enables the early-exit pruning below
        List<List<Integer>> result = new ArrayList<>();
        search(candidates, target, 0, new ArrayList<>(), result);
        return result;
    }

    private void search(int[] values, int remaining, int start,
                        List<Integer> path, List<List<Integer>> result) {
        if (remaining == 0) {
            result.add(new ArrayList<>(path));
            return;
        }
        // prune once too big
        for (int i = start; i < values.length && values[i] <= remaining; i++) {
            path.add(values[i]);
            // same index i: reuse allowed
            search(values, remaining - values[i], i, path, result);
            // undo the choice before trying the next candidate
            path.remove(path.size() - 1);
        }
    }
}

word-search.code:
class Solution {
    public boolean exist(char[][] board, String word) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (dfs(board, word, r, c, 0)) return true; // try every starting cell
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int r, int c, int i) {
        if (i == word.length()) return true; // matched every character
        if (r < 0 || r == board.length || c < 0 || c == board[0].length
                || board[r][c] != word.charAt(i)) return false;
        char saved = board[r][c];
        board[r][c] = '#'; // mark as visited in place, no extra memory needed
        boolean found = dfs(board, word, r + 1, c, i + 1)
            || dfs(board, word, r - 1, c, i + 1)
            || dfs(board, word, r, c + 1, i + 1)
            || dfs(board, word, r, c - 1, i + 1);
        // restore before returning, whether this path succeeded or not
        board[r][c] = saved;
        return found;
    }
}

