class Trie {
    private static class TrieNode {
        TrieNode[] next = new TrieNode[26]; // one slot per lowercase letter
        boolean terminal; // true if a word ends exactly here
    }

    private final TrieNode root = new TrieNode();

    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            if (node.next[index] == null) node.next[index] = new TrieNode();
            node = node.next[index];
        }
        node.terminal = true;
    }

    public boolean search(String word) {
        TrieNode node = find(word);
        return node != null && node.terminal; // path exists AND ends a word
    }

    public boolean startsWith(String prefix) {
        return find(prefix) != null; // path existing is enough, no terminal check
    }

    private TrieNode find(String text) {
        TrieNode node = root;
        for (char c : text.toCharArray()) {
            node = node.next[c - 'a'];
            if (node == null) return null;
        }
        return node;
    }
}

