class WordDictionary {
    private static class TrieNode {
        TrieNode[] next = new TrieNode[26];
        boolean terminal;
    }

    private final TrieNode root = new TrieNode();

    public void addWord(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            if (node.next[index] == null) node.next[index] = new TrieNode();
            node = node.next[index];
        }
        node.terminal = true;
    }

    public boolean search(String word) {
        return search(word, 0, root);
    }

    private boolean search(String word, int i, TrieNode node) {
        if (i == word.length()) return node.terminal;
        char c = word.charAt(i);
        if (c != '.') {
            TrieNode child = node.next[c - 'a'];
            return child != null && search(word, i + 1, child);
        }
        for (TrieNode child : node.next) { // '.' tries every possible branch
            if (child != null && search(word, i + 1, child)) return true;
        }
        return false;
    }
}

