class Solution {
    private static class TrieNode {
        TrieNode[] next = new TrieNode[26];
        String word; // non-null exactly at nodes where a dictionary word ends
    }

    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String word : words) { // build one trie of every word up front
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                int i = c - 'a';
                if (node.next[i] == null) node.next[i] = new TrieNode();
                node = node.next[i];
            }
            node.word = word;
        }

        List<String> result = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) dfs(board, r, c, root, result);
        }
        return result;
    }

    private void dfs(char[][] board, int r, int c, TrieNode node, List<String> out) {
        if (r < 0 || r == board.length || c < 0 || c == board[0].length
                || board[r][c] == '#') return;
        char letter = board[r][c];
        TrieNode child = node.next[letter - 'a'];
        if (child == null) return; // no word in the trie continues this way
        if (child.word != null) {
            out.add(child.word);
            child.word = null; // avoid adding the same word twice via a different path
        }
        board[r][c] = '#'; // mark visited for this DFS branch
        dfs(board, r + 1, c, child, out);
        dfs(board, r - 1, c, child, out);
        dfs(board, r, c + 1, child, out);
        dfs(board, r, c - 1, child, out);
        board[r][c] = letter; // restore for other starting points
    }
}

