class Solution {
    public int numIslands(char[][] grid) {
        int islands = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '1') {
                    islands++;
                    // sink the whole connected island so it isn't counted again
                    flood(grid, r, c);
                }
            }
        }
        return islands;
    }

    private void flood(char[][] grid, int r, int c) {
        if (r < 0 || r == grid.length || c < 0 || c == grid[0].length
                || grid[r][c] != '1') return;
        grid[r][c] = '0'; // mark visited in place (doubles as the visited check above)
        flood(grid, r + 1, c);
        flood(grid, r - 1, c);
        flood(grid, r, c + 1);
        flood(grid, r, c - 1);
    }
}

