class Solution {
    public Node cloneGraph(Node node) {
        return clone(node, new HashMap<>());
    }

    private Node clone(Node node, Map<Node, Node> copies) {
        if (node == null) return null;
        // already cloned, avoid infinite recursion
        if (copies.containsKey(node)) return copies.get(node);
        Node copy = new Node(node.val);
        // register before recursing into neighbors, in case of a cycle
        copies.put(node, copy);
        for (Node neighbor : node.neighbors) {
            copy.neighbors.add(clone(neighbor, copies));
        }
        return copy;
    }
}

