class Solution {
    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        int rows = heights.length, cols = heights[0].length;
        boolean[][] pacific = new boolean[rows][cols];
        boolean[][] atlantic = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) { // start DFS from every border cell of each ocean
            dfs(heights, r, 0, pacific);
            dfs(heights, r, cols - 1, atlantic);
        }
        for (int c = 0; c < cols; c++) {
            dfs(heights, 0, c, pacific);
            dfs(heights, rows - 1, c, atlantic);
        }
        List<List<Integer>> result = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                // reachable from both
                if (pacific[r][c] && atlantic[r][c]) result.add(Arrays.asList(r, c));
            }
        }
        return result;
    }

    private void dfs(int[][] h, int r, int c, boolean[][] seen) {
        if (seen[r][c]) return;
        seen[r][c] = true;
        int[][] directions = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : directions) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < h.length && nc >= 0 && nc < h[0].length
                    // flow backward: only to same/higher ground
                    && !seen[nr][nc] && h[nr][nc] >= h[r][c]) {
                dfs(h, nr, nc, seen);
            }
        }
    }
}

