class Solution {
    public String foreignDictionary(String[] words) {
        Map<Character, Set<Character>> graph = new HashMap<>();
        Map<Character, Integer> indegree = new HashMap<>();
        for (String word : words) {
            for (char c : word.toCharArray()) {
                graph.computeIfAbsent(c, k -> new HashSet<>());
                indegree.putIfAbsent(c, 0);
            }
        }
        // compare each adjacent pair of words
        for (int i = 0; i + 1 < words.length; i++) {
            String first = words[i], second = words[i + 1];
            int limit = Math.min(first.length(), second.length());
            int j = 0;
            // find first difference
            while (j < limit && first.charAt(j) == second.charAt(j)) j++;
            if (j == limit) {
                // longer word can't come first
                if (first.length() > second.length()) return "";
                continue;
            }
            // this is the only valid ordering clue
            char from = first.charAt(j), to = second.charAt(j);
            if (graph.get(from).add(to)) indegree.put(to, indegree.get(to) + 1);
        }

        Queue<Character> queue = new ArrayDeque<>();
        for (char c : indegree.keySet()) if (indegree.get(c) == 0) queue.offer(c);
        StringBuilder order = new StringBuilder();
        while (!queue.isEmpty()) {
            char c = queue.poll();
            order.append(c);
            for (char next : graph.get(c)) {
                indegree.put(next, indegree.get(next) - 1);
                if (indegree.get(next) == 0) queue.offer(next);
            }
        }
        // shorter means a cycle existed
        return order.length() == indegree.size() ? order.toString() : "";
    }
}

