class Solution {
    public int climbStairs(int n) {
        int oneStepBack = 1, twoStepsBack = 1; // ways to reach the previous two steps
        for (int i = 2; i <= n; i++) {
            int current = oneStepBack + twoStepsBack; // arrive via a 1-step or a 2-step
            twoStepsBack = oneStepBack;
            oneStepBack = current;
        }
        return oneStepBack;
    }
}

