class Solution {
    public int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        // First/last houses are adjacent in a circle, so run the linear version twice,
        // each time excluding one end, and take the better result.
        return Math.max(robRange(nums, 0, nums.length - 2),
                         robRange(nums, 1, nums.length - 1));
    }

    private int robRange(int[] nums, int start, int end) {
        int skipped = 0, taken = 0;
        for (int i = start; i <= end; i++) {
            int current = Math.max(taken, skipped + nums[i]);
            skipped = taken;
            taken = current;
        }
        return taken;
    }
}

