class Solution {
    public String longestPalindrome(String s) {
        int start = 0, bestLength = 0;
        for (int center = 0; center < s.length(); center++) {
            int oddLength = expand(s, center, center);       // odd-length palindromes
            int evenLength = expand(s, center, center + 1);  // even-length palindromes
            int length = Math.max(oddLength, evenLength);
            if (length > bestLength) {
                bestLength = length;
                start = center - (length - 1) / 2;
            }
        }
        return s.substring(start, start + bestLength);
    }

    private int expand(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }
}

