class Solution {
    public int countSubstrings(String s) {
        int total = 0;
        for (int i = 0; i < s.length(); i++) {
            total += countAround(s, i, i);       // odd-length palindromes centered at i
            // even-length palindromes centered between i, i+1
            total += countAround(s, i, i + 1);
        }
        return total;
    }

    private int countAround(String s, int left, int right) {
        int count = 0;
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            count++;
            left--;
            right++;
        }
        return count;
    }
}

