class Solution {
    public int numDecodings(String s) {
        if (s.isEmpty() || s.charAt(0) == '0') return 0; // leading zero can never decode
        // ways to decode the string ending 2 / 1 positions back
        int twoBack = 1, oneBack = 1;
        for (int i = 1; i < s.length(); i++) {
            int current = 0;
            // treat s[i] as a single-digit token
            if (s.charAt(i) != '0') current += oneBack;
            int twoDigit = (s.charAt(i - 1) - '0') * 10 + (s.charAt(i) - '0');
            // treat s[i-1..i] as one token
            if (twoDigit >= 10 && twoDigit <= 26) current += twoBack;
            twoBack = oneBack;
            oneBack = current;
        }
        return oneBack;
    }
}

