class Solution {
    public int maxProduct(int[] nums) {
        int maxSoFar = nums[0], minSoFar = nums[0], best = nums[0]; // track both extremes
        for (int i = 1; i < nums.length; i++) {
            int value = nums[i];
            int prevMax = maxSoFar, prevMin = minSoFar;
            // A negative value can turn the smallest running product into the largest.
            maxSoFar = Math.max(value, Math.max(value * prevMax, value * prevMin));
            minSoFar = Math.min(value, Math.min(value * prevMax, value * prevMin));
            best = Math.max(best, maxSoFar);
        }
        return best;
    }
}

