class Solution {
    public int lengthOfLIS(int[] nums) {
        // smallest possible tail value for each subsequence length
        int[] tails = new int[nums.length];
        int size = 0;
        for (int value : nums) {
            // binary search for value's insertion point in tails
            int left = 0, right = size;
            while (left < right) {
                int mid = (left + right) >>> 1;
                if (tails[mid] < value) left = mid + 1;
                else right = mid;
            }
            tails[left] = value;
            // value extended the longest subsequence found so far
            if (left == size) size++;
        }
        return size;
    }
}

