class Solution {
    public int uniquePaths(int m, int n) {
        // rolled 1D row: dp[c] = paths to reach column c in current row
        long[] dp = new long[n];
        // top row: only one way to reach any cell (move right the whole way)
        Arrays.fill(dp, 1);
        for (int r = 1; r < m; r++) {
            // from above (unchanged) or from the left
            for (int c = 1; c < n; c++) dp[c] += dp[c - 1];
        }
        return (int) dp[n - 1];
    }
}

