class Solution {
    public int longestCommonSubsequence(String a, String b) {
        int[] prev = new int[b.length() + 1]; // rolled DP: previous row of the 2D table
        for (int i = 1; i <= a.length(); i++) {
            int[] current = new int[b.length() + 1];
            for (int j = 1; j <= b.length(); j++) {
                current[j] = a.charAt(i - 1) == b.charAt(j - 1)
                    // characters match: extend the diagonal
                    ? prev[j - 1] + 1
                    // otherwise take the better of two neighbors
                    : Math.max(prev[j], current[j - 1]);
            }
            prev = current;
        }
        return prev[b.length()];
    }
}

