class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        // sort by end time (greedy choice)
        Arrays.sort(intervals, Comparator.comparingInt(x -> x[1]));
        int kept = 0, lastEnd = Integer.MIN_VALUE;
        for (int[] interval : intervals) {
            if (interval[0] >= lastEnd) { // no overlap with the last kept interval
                kept++;
                lastEnd = interval[1];
            }
        }
        return intervals.length - kept; // everything not kept must be removed
    }
}

