class Solution {
    public int minMeetingRooms(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        // sorted independently -- only counts matter, not which meeting is which
        Arrays.sort(starts);
        Arrays.sort(ends);
        int startPointer = 0, endPointer = 0, rooms = 0, best = 0;
        while (startPointer < n) {
            // a meeting starts before the earliest ends
            if (starts[startPointer] < ends[endPointer]) {
                rooms++;
                best = Math.max(best, rooms);
                startPointer++;
            } else {
                rooms--; // free up a room instead
                endPointer++;
            }
        }
        return best;
    }
}

