class Solution {
    public List<Integer> spiralOrder(int[][] matrix) {
        List<Integer> order = new ArrayList<>();
        int top = 0, bottom = matrix.length - 1;
        int left = 0, right = matrix[0].length - 1;
        // four shrinking boundaries track the unvisited region
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++) order.add(matrix[top][c]);
            top++;
            for (int r = top; r <= bottom; r++) order.add(matrix[r][right]);
            right--;
            if (top <= bottom) { // guards against re-visiting a single remaining row
                for (int c = right; c >= left; c--) order.add(matrix[bottom][c]);
                bottom--;
            }
            if (left <= right) { // guards against re-visiting a single remaining column
                for (int r = bottom; r >= top; r--) order.add(matrix[r][left]);
                left++;
            }
        }
        return order;
    }
}

