class Solution {
    public int[] countBits(int n) {
        int[] dp = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            // reuse the answer for i with its lowest bit dropped
            dp[i] = dp[i >>> 1] + (i & 1);
        }
        return dp;
    }
}

