class Solution {
    public int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1); // shift result left, drop in n's lowest bit
            n >>>= 1; // unsigned shift avoids sign-extension corrupting the bit pattern
        }
        return result;
    }
}

