class Solution {
    public int missingNumber(int[] nums) {
        // account for index n up front, since indices only run 0..n-1
        int result = nums.length;
        for (int i = 0; i < nums.length; i++) {
            // every present index/value pair cancels via XOR, leaving the gap
            result ^= i ^ nums[i];
        }
        return result;
    }
}

