class Solution {
    public int getSum(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1; // bits where both operands are 1 generate a carry
            a ^= b;                   // XOR adds without carrying
            b = carry;                // repeat until no carry remains
        }
        return a;
    }
}
